-- Soundboard_SanityCapped
--
-- A companion pack for the Soundboard addon. It does not modify Soundboard; it
-- loads after it and adds its own sounds to the same table, so they behave like
-- the built-in ones (menu, search, favorites, slash commands, and playing for
-- everyone in your group or guild who also has this pack).
--
-- The sounds themselves are listed in SoundData.lua, which is generated by
-- tools/build_sounds.py. Don't edit that file by hand.

local ADDON, ns = ...

local CATEGORY = "Sanity Capped"

local function warn(msg)
	DEFAULT_CHAT_FRAME:AddMessage("|cffff6666" .. ADDON .. ":|r " .. msg)
end

local function info(msg)
	DEFAULT_CHAT_FRAME:AddMessage("|cff8fd4ff" .. CATEGORY .. ":|r " .. msg)
end

-- ---------------------------------------------------------------------------
-- Adding our sounds to Soundboard
-- ---------------------------------------------------------------------------

local loaded, skipped = {}, {}

-- The release also carries the emote pack, and plenty of people only want
-- that. Without Soundboard this addon stays quiet and does nothing.
local baseMissing = type(soundboard_data) ~= "table" or type(Soundboard) ~= "table"

-- Soundboard turns every key into a slash command about a second after it
-- loads. We normally get in before that, but registering our own the same way
-- means the commands exist even if we don't.
local function RegisterSlashCommand(key)
	SlashCmdList["SOUNDBOARD_" .. key] = function()
		Soundboard:SaySoundboardKey(key)
	end
	_G["SLASH_SOUNDBOARD_" .. key .. "1"] = "/" .. key
end

local function AddSounds()
	for _, sound in ipairs(ns.sounds) do
		-- Never replace a sound from Soundboard or another pack: the key is what
		-- gets sent to other players, so it has to mean the same file for everyone.
		if soundboard_data[sound.key] == nil then
			soundboard_data[sound.key] = {
				["text"] = sound.name,
				["category"] = CATEGORY,
				["file"] = ns.SOUND_ROOT .. sound.file,
				["duration"] = sound.duration,
			}
			RegisterSlashCommand(sound.key)
			loaded[#loaded + 1] = sound
		else
			skipped[#skipped + 1] = sound
		end
	end
end

-- ---------------------------------------------------------------------------
-- Slash command
-- ---------------------------------------------------------------------------

local function ShowList()
	info(#loaded .. " sound(s):")
	local line, perLine = "", 0
	for _, sound in ipairs(loaded) do
		line = line .. "/" .. sound.key .. "   "
		perLine = perLine + 1
		if perLine == 4 then
			DEFAULT_CHAT_FRAME:AddMessage(line)
			line, perLine = "", 0
		end
	end
	if perLine > 0 then
		DEFAULT_CHAT_FRAME:AddMessage(line)
	end
end

SLASH_SANITYSOUNDS1 = "/scsounds"
SLASH_SANITYSOUNDS2 = "/sanitysounds"
SlashCmdList["SANITYSOUNDS"] = function(msg)
	msg = (msg or ""):lower():match("^%s*(.-)%s*$")
	if baseMissing then
		info("the Soundboard addon isn't installed or is disabled, so the sounds are off.")
	elseif msg == "list" then
		ShowList()
	else
		info(#loaded .. " sound(s) loaded. |cffaaaaaa/scsounds list|r to see them all.")
	end
end

-- ---------------------------------------------------------------------------
-- Boot
-- ---------------------------------------------------------------------------

if type(ns.sounds) ~= "table" then
	warn("SoundData.lua is missing. Run tools/build_sounds.py.")
elseif not baseMissing then
	AddSounds()
	for _, sound in ipairs(skipped) do
		warn("/" .. sound.key .. " is already a Soundboard sound, so " .. sound.name .. " was skipped.")
	end
end
